#!/usr/bin/env bash
# Generate tool-specific agent/skill adapters from the canonical sources in
# .sdlc/framework/. Edit the sources, never the generated files.
#
# Usage: .sdlc/sync.sh [--target cursor|claude|all] [--dest DIR] [--check]
#
#   --target  Which tool(s) to generate for (default: all)
#   --dest    Root to write .cursor/ and .claude/ under (default: the folder
#             that contains .sdlc/). Use --dest "$HOME" for a user-level install.
#   --check   Write nothing; exit 1 if the generated files are out of date.
#
# Only files carrying the generated marker are replaced or removed, so other
# agents and skills in .cursor/ or .claude/ are left alone.
#
# Requires bash 3.2+ and standard POSIX tools (macOS default bash is fine).

set -euo pipefail

SDLC_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
FRAMEWORK_DIR="$SDLC_DIR/framework"
MARKER="Generated by .sdlc/sync.sh"

# Read-only agents get this tool allowlist in Claude Code (no Edit/Write).
CLAUDE_READONLY_TOOLS="Read, Grep, Glob, Bash"

target="all"
dest="$(dirname "$SDLC_DIR")"
check=0

usage() { sed -n '2,15p' "${BASH_SOURCE[0]}" | sed 's/^# \{0,1\}//'; }

while [ $# -gt 0 ]; do
  case "$1" in
    --target) target="${2:-}"; shift 2 ;;
    --dest) dest="${2:-}"; shift 2 ;;
    --check) check=1; shift ;;
    -h|--help) usage; exit 0 ;;
    *) echo "sync.sh: unknown argument: $1" >&2; usage >&2; exit 2 ;;
  esac
done

case "$target" in
  cursor) tools="cursor" ;;
  claude) tools="claude" ;;
  all) tools="cursor claude" ;;
  *) echo "sync.sh: --target must be cursor, claude, or all" >&2; exit 2 ;;
esac

[ -d "$FRAMEWORK_DIR/agents" ] || { echo "sync.sh: missing $FRAMEWORK_DIR/agents" >&2; exit 1; }
[ -d "$dest" ] || { echo "sync.sh: --dest does not exist: $dest" >&2; exit 1; }

# render_agent <tool> <source> : print the adapter for one agent to stdout.
# Canonical frontmatter fields: name, description, model, readonly.
#   cursor: passed through unchanged (Cursor reads readonly natively).
#   claude: readonly is dropped; readonly: true becomes a tools allowlist.
render_agent() {
  awk -v tool="$1" -v marker="$MARKER" -v src="${2#"$SDLC_DIR/"}" -v ro_tools="$CLAUDE_READONLY_TOOLS" '
    NR == 1 && $0 == "---" { in_fm = 1; print; next }
    in_fm && $0 == "---" {
      if (tool == "claude" && readonly == "true") print "tools: " ro_tools
      print
      print ""
      print "<!-- " marker " from .sdlc/" src " - do not edit; edit the source and re-run. -->"
      in_fm = 0
      next
    }
    in_fm && /^readonly:/ {
      readonly = $2
      if (tool == "claude") next
    }
    { print }
  ' "$2"
}

# render_skill_file <source> : print one skill file with the marker inserted
# after its frontmatter (or at the top when it has none).
render_skill_file() {
  awk -v marker="$MARKER" -v src="${1#"$SDLC_DIR/"}" '
    function stamp() { print "<!-- " marker " from .sdlc/" src " - do not edit; edit the source and re-run. -->" }
    NR == 1 && $0 == "---" { in_fm = 1; print; next }
    NR == 1 { stamp(); print ""; print; next }
    in_fm && $0 == "---" { print; print ""; stamp(); in_fm = 0; next }
    { print }
  ' "$1"
}

# generate <tool> <out_root> : write <out_root>/.<tool>/{agents,skills}.
generate() {
  local tool="$1" out="$2" f name rel
  mkdir -p "$out/.$tool/agents" "$out/.$tool/skills"
  for f in "$FRAMEWORK_DIR"/agents/*.md; do
    render_agent "$tool" "$f" > "$out/.$tool/agents/$(basename "$f")"
  done
  for d in "$FRAMEWORK_DIR"/skills/*/; do
    name="$(basename "$d")"
    (cd "$d" && find . -type f) | while read -r rel; do
      rel="${rel#./}"
      mkdir -p "$(dirname "$out/.$tool/skills/$name/$rel")"
      render_skill_file "$d$rel" > "$out/.$tool/skills/$name/$rel"
    done
  done
}

# generated_paths <tool_dir> : list generated agents and skill dirs (relative).
generated_paths() {
  local dir="$1" f
  [ -d "$dir" ] || return 0
  for f in "$dir"/agents/*.md; do
    [ -f "$f" ] && grep -q "$MARKER" "$f" && echo "agents/$(basename "$f")"
  done
  for f in "$dir"/skills/*/SKILL.md; do
    [ -f "$f" ] && grep -q "$MARKER" "$f" && echo "skills/$(basename "$(dirname "$f")")"
  done
  return 0
}

tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT

status=0
for tool in $tools; do
  generate "$tool" "$tmp"
  live="$dest/.$tool"

  if [ "$check" -eq 1 ]; then
    expected="$(generated_paths "$tmp/.$tool")"
    actual="$(generated_paths "$live")"
    if [ "$expected" != "$actual" ]; then
      echo "sync.sh: .$tool has missing or stale generated files" >&2
      status=1
    fi
    for p in $expected; do
      if ! diff -r "$tmp/.$tool/$p" "$live/$p" > /dev/null 2>&1; then
        echo "sync.sh: .$tool/$p is out of date" >&2
        status=1
      fi
    done
    continue
  fi

  # Remove previously generated files (marker-based), then install fresh ones.
  for p in $(generated_paths "$live"); do
    rm -rf "${live:?}/$p"
  done
  mkdir -p "$live/agents" "$live/skills"
  cp "$tmp/.$tool"/agents/*.md "$live/agents/"
  cp -R "$tmp/.$tool"/skills/* "$live/skills/"
  echo "sync.sh: wrote $live/agents and $live/skills"
done

if [ "$check" -eq 1 ]; then
  if [ "$status" -eq 0 ]; then
    echo "sync.sh: generated files are up to date"
  else
    echo "sync.sh: run .sdlc/sync.sh to regenerate" >&2
  fi
fi
exit "$status"
